const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const c=require('./core.js');
const row=(event,data={},sid='s')=>JSON.stringify({session_id:sid,event,data});
test('prepared and response join same request without doubling call count',()=>{const s=c.parseLog([row('request_prepared',{step:1,attempt:1,request_id:'r'}),row('request',{step:1,attempt:1,request_id:'r'}),row('response',{step:1,attempt:1,latency_ms:12}),row('manual_retry')].join('\n'),'x/events.jsonl').sessions[0];assert.equal(s.requests.length,1);assert.equal(s.requests[0].events.length,3);assert.equal(c.summary(s).calls,1);assert.equal(s.events.length,4)});
test('same step separate attempts remain separate',()=>{const s=c.parseLog([row('request',{step:4,attempt:1,request_id:'a'}),row('request',{step:4,attempt:2,request_id:'b'})].join('\n'),'x').sessions[0];assert.equal(s.requests.length,2)});
test('sessions do not cross associate identical request ids',()=>{const s=c.parseLog([row('request',{request_id:'r'},'a'),row('request',{request_id:'r'},'b')].join('\n'),'x').sessions;assert.equal(s.length,2);assert.equal(s[0].events.length,1)});
test('malformed lines are reported with original line numbers',()=>{const r=c.parseLog('\ufeff'+row('start')+'\nBROKEN\n\n'+row('end',{result:'STOPPED'}),'x');assert.equal(r.warnings.length,1);assert.match(r.warnings[0],/第 2 行/);assert.equal(r.sessions[0].events[1].line,4)});
test('ambiguous fallback is not guessed',()=>{const s=c.parseLog([row('request',{request_id:'a',step:1,attempt:1}),row('request',{request_id:'b',step:1,attempt:1}),row('response',{step:1,attempt:1})].join('\n'),'x').sessions[0];assert.equal(s.warnings.length,1);assert.equal(s.requests[0].events.length,1)});
test('attachments are local to source directory, reject traversal and ambiguity',()=>{const f=[{path:'a/p.jpg'},{path:'b/p.jpg'}];assert.equal(c.resolveRef(f,'b/events.jsonl','p.jpg').file.path,'b/p.jpg');assert.ok(c.resolveRef(f,'c/events.jsonl','p.jpg').error);assert.ok(c.resolveRef(f,'a/events.jsonl','../b/p.jpg').error);assert.ok(c.resolveRef([{path:'p.jpg'},{path:'p.jpg'}],'events.jsonl','p.jpg').error)});
test('returned decision is distinct from displayed guidance; discarded takes priority',()=>{const s=c.parseLog([row('decision',{request_id:'r'}),row('invalid_decision',{request_id:'r',error:'guard'}),row('response',{request_id:'q',error:'cancel'}),row('discarded',{request_id:'q'})].join('\n'),'x').sessions[0];assert.equal(s.requests[0].status,'被拒绝 / 出错');assert.equal(s.requests[1].status,'已丢弃');assert.equal(c.summary(s).guidance,0)});
test('real exported run gives independently checked totals and attachment refs',()=>{const path=process.env.LOG_FIXTURE;if(!path)throw Error('LOG_FIXTURE must point to actual exported events.jsonl');const s=c.parseLog(fs.readFileSync(path,'utf8'),'run/events.jsonl').sessions[0];const m=c.summary(s);assert.equal(m.calls,27);assert.equal(m.guidance,6);assert.equal(m.invalid,16);assert.equal(m.result,'STOPPED');assert.equal(m.median,1336);const last=s.requests.find(r=>r.step===24&&r.attempt===2);assert.match(last.refs.screenshot_ref,/_24_2.jpg$/);assert.match(last.error.data.error,/联系人/)});

test('explicit app cancellation is displayed separately from transport failure',()=>{const s=c.parseLog([row('request',{request_id:'r'}),row('request_cancelled_by_app',{request_id:'r',reason:'页面状态变化'}),row('response',{request_id:'r',error:'页面状态变化',error_code:'APP_CANCELLED',exception_type:'SocketException'})].join('\n'),'x').sessions[0];assert.equal(s.requests[0].status,'App 已取消');assert.equal(s.requests[0].error,undefined);assert.match(s.requests[0].search,/页面状态变化/)});


test('review joins request response and candidate without pretending it is a user action',()=>{const s=c.parseLog([row('request',{request_id:'review',step:0,attempt:1,purpose:'workflow_review'}),row('response',{request_id:'review',content:'{}',purpose:'workflow_review'}),row('workflow_candidate_saved',{request_id:'review',version_id:'v'})].join('\n'),'x').sessions[0];assert.equal(s.requests.length,1);assert.equal(s.requests[0].purpose,'workflow_review');assert.equal(s.requests[0].status,'流程候选已保存');assert.equal(c.summary(s).calls,1);assert.equal(c.summary(s).guidance,0)});
